<section class="page-heading"><p class="eyebrow">FIND YOUR WAY</p><h1>Find a ride.</h1><p>Search shared journeys headed in your direction.</p></section>
<form class="search-panel row g-3 align-items-end" method="get" action="index.php"><input type="hidden" name="page" value="find"><div class="col-md"><label class="form-label" for="origin">From</label><input class="form-control" id="origin" name="origin" value="<?= e($data['origin']) ?>" placeholder="e.g. Sullia"></div><div class="col-md"><label class="form-label" for="destination">To</label><input class="form-control" id="destination" name="destination" value="<?= e($data['destination']) ?>" placeholder="e.g. Mangaluru"></div><div class="col-md-3"><label class="form-label" for="date">Date</label><input class="form-control" type="date" min="<?= e(date('Y-m-d')) ?>" id="date" name="date" value="<?= e($data['date']) ?>"></div><div class="col-md-3"><label class="form-label" for="time_after">Depart at or after</label><input class="form-control" type="time" id="time_after" name="time_after" value="<?= e($data['time_after']) ?>"></div><div class="col-md-3"><label class="form-label" for="min_seats">Seats needed</label><select class="form-select" id="min_seats" name="min_seats"><?php for($n=1;$n<=8;$n++): ?><option value="<?= $n ?>" <?= $data['min_seats']===$n?'selected':'' ?>><?= $n ?> or more</option><?php endfor; ?></select></div><div class="col-md-3"><label class="form-label" for="max_contribution">Max. est. per seat (₹)</label><input class="form-control" type="number" min="0" step="50" id="max_contribution" name="max_contribution" value="<?= e($data['max_contribution']) ?>" placeholder="Any amount"></div><div class="col-md-auto"><button class="btn btn-dark">Search <span aria-hidden="true">→</span></button></div></form>
<div class="results-head"><h2><?= count($data['rides']) ?> upcoming <?= count($data['rides'])===1?'ride':'rides' ?></h2><span>Route matches are based on the origin and destination you enter.</span></div>
<?php if (!$data['rides']): ?><div class="empty-state"><span class="empty-icon">↗</span><h3>No rides match just yet.</h3><p>Try a nearby town or another date. Drivers can also publish a new route.</p><a href="index.php?page=offer" class="btn btn-outline-dark">Offer a ride</a></div><?php endif; ?>
<div class="ride-list"><?php foreach($data['rides'] as $ride): ?><article class="ride-card"><div class="ride-main"><div class="ride-route"><span><?= e($ride['origin']) ?></span><i aria-hidden="true"></i><span><?= e($ride['destination']) ?></span></div><p class="ride-meta"><?= e(date('D, M j',strtotime($ride['travel_date']))) ?> <span>·</span> <?= e(substr($ride['departure_time'],0,5)) ?> <span>·</span> <?= (int)$ride['seats_left'] ?> seats left</p><div class="driver-summary"><span class="avatar"><?= e(strtoupper(substr($ride['driver_name'],0,1))) ?></span><span><strong><?= e($ride['driver_name']) ?></strong><small><?= e($ride['vehicle_model'] ?: 'Vehicle details pending') ?> · <?= $ride['rating'] ? number_format((float)$ride['rating'],1).' ★' : 'New driver' ?></small></span><span class="verify-tag">● <?= 'Profile '.($ride['is_sample']?'sample':'listed') ?></span></div><?php if($ride['pickup_points']): ?><p class="ride-note">Pickup: <?= e($ride['pickup_points']) ?></p><?php endif; ?><?php if($ride['notes']): ?><p class="ride-note"><?= e($ride['notes']) ?></p><?php endif; ?><a class="map-link" href="https://www.openstreetmap.org/search?query=<?= rawurlencode($ride['origin'].' to '.$ride['destination']) ?>" target="_blank" rel="noopener noreferrer">Look up locations in OpenStreetMap ↗</a></div><div class="ride-price"><small>EST. PER SEAT</small><strong>₹<?= number_format((float)$ride['estimated_cost']/max(1,(int)$ride['total_seats']),0) ?></strong><span>of ₹<?= number_format((float)$ride['estimated_cost'],0) ?> total</span><?php if($ride['is_sample']): ?><span class="sample-badge">Sample</span><?php endif; ?><?php if(current_user() && current_user()['role']==='passenger' && $ride['seats_left']>0 && !$ride['is_sample']): ?><form method="post" action="index.php" class="book-inline"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="book"><input type="hidden" name="return_page" value="find"><input type="hidden" name="ride_id" value="<?= (int)$ride['id'] ?>"><label class="visually-hidden" for="seats-<?= (int)$ride['id'] ?>">Seats</label><select id="seats-<?= (int)$ride['id'] ?>" name="seats" class="form-select form-select-sm"><?php for($s=1;$s<=min(8,(int)$ride['seats_left']);$s++): ?><option value="<?= $s ?>"><?= $s ?> seat<?= $s>1?'s':'' ?></option><?php endfor; ?></select><button class="btn btn-primary btn-sm">Request</button></form><?php elseif(!current_user()): ?><a class="btn btn-primary btn-sm" href="index.php?page=login">Log in to request</a><?php elseif($ride['is_sample']): ?><small>Demo route only</small><?php endif; ?></div></article><?php endforeach; ?></div>